""" Every number used in the thesis is generated by this module"""
from __future__ import annotations

import argparse
import collections
import csv
import glob
import json
import math
import os
import sys

import numpy as np
import yaml
from scipy import stats

from annin_ar4_calibration.benchmark import analyze
from annin_ar4_calibration.core import (
    geometry, joint_sampling, kinematic_model, kinematic_solver, metrics, perturbation, storage)

REF = 'method=joint_trf|ridge_lambda=0.001'
MOUNTINGS = ('eye_in_hand', 'eye_to_hand')
SIGMAS = (0.0, 0.5, 1.0, 2.0)
LAMBDAS = ('0.001', '1e-06', '1e-09')
METHODS_KIN = ('sequential', 'joint_trf', 'joint_lm')
METHODS_HE = ('PARK', 'TSAI', 'HORAUD', 'DANIILIDIS', 'ANDREFF')
SEVERE_MM = 5.0
CORRUPT_ROT_DEG, CORRUPT_TRANS_MM = 1.0, 10.0
SCALE_FIT_MAX_DIST_M = 0.8
GEO_CACHE = 'thesis_geometry_cache.json'
SAMPLING_MARGIN_DEG = 15.0
CAMERA_HFOV_RAD, CAMERA_WIDTH, CAMERA_HEIGHT = 1.2, 1280, 720


def _num(v):
    if v in ('True', 'False'):
        return 1.0 if v == 'True' else 0.0
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


def _mean(xs):
    xs = [x for x in xs if x is not None]
    return float(np.mean(xs)) if xs else float('nan')


def _spearman(a, b):
    return float(stats.spearmanr(a, b).statistic)


# data access

class Benchmark:
    def __init__(self, out_dir: str):
        self.out_dir = out_dir
        self.rows = list(csv.DictReader(open(os.path.join(out_dir, 'results.csv'))))
        self.runs = {}
        for d in sorted(glob.glob(os.path.join(out_dir, 'runs', '*', ''))):
            man = os.path.join(d, 'manifest.yaml')
            if os.path.exists(man):
                self.runs[os.path.basename(d.rstrip('/'))] = (d, yaml.safe_load(open(man)))
        self._kin = None

    def value(self, run, wp, variant, metric):
        for r in self._index().get((run, wp, variant), []):
            if r['metric'] == metric:
                return _num(r['value'])
        return None

    def _index(self):
        if not hasattr(self, '_idx'):
            self._idx = collections.defaultdict(list)
            for r in self.rows:
                self._idx[(r['run_id'], r['work_package'], r['variant'])].append(r)
        return self._idx

    def select(self, **flt):
        return [r for r in self.rows if all(r.get(k) == v for k, v in flt.items())]

    def kinematic_runs(self):
        if self._kin is not None:
            return self._kin
        out = {}
        for run, (d, man) in self.runs.items():
            if man['spec'].get('sweep') != 'sim_wp4':
                continue
            col = man['spec']['collection']
            art = analyze.RunArtifacts(d)
            f = art.path('kinematic_samples.npy')
            s = storage.load_samples(f, ncols=13)
            names = (storage.load_meta(f) or {}).get('arm_joint_names') or list(perturbation.DEFAULT_JOINT_NAMES)
            jf = art.joint_frames(names)
            tk = art.ground_truth['kinematic_calibration']
            tc = perturbation.corrections_from_dict(tk['corrections'], names)
            theta = s[:, :6]
            camR, camt = geometry.batch_samples_to_rt(s[:, 6:13])
            ct = col['calibration_type']
            kR, kt = metrics.rt_from_transform_dict(art.ground_truth['hand_eye_calibration']['transform'])
            mR, mt = metrics.rt_from_transform_dict(tk['mount_offset'])
            pR, pt = kinematic_model.forward_kinematics_batch(theta, jf, tc)
            lR, lt, rR, rt = kinematic_solver._lhs_rhs_batch(ct, pR, pt, mR, mt, kR, kt, camR, camt)
            res_t = np.linalg.norm(lt - rt, axis=1) * 1000.0
            res_r = np.degrees(np.linalg.norm(geometry.batch_rotation_matrix_to_rotvec(
                np.einsum('nji,njk->nik', rR, lR)), axis=1))
            if ct == 'eye_in_hand':
                R_bc = pR @ kR
                t_bc = np.einsum('nij,j->ni', pR, kt) + pt
                t_bt = np.broadcast_to(mt, t_bc.shape)
            else:
                R_bc = np.broadcast_to(kR, pR.shape)
                t_bc = np.broadcast_to(kt, pt.shape)
                t_bt = np.einsum('nij,j->ni', pR, mt) + pt
            true_cam = np.einsum('nji,nj->ni', R_bc, t_bt - t_bc)
            err = (camt - true_cam) * 1000.0
            view = true_cam / np.linalg.norm(true_cam, axis=1)[:, None]
            along = np.einsum('ni,ni->n', err, view)
            nominal = metrics.fk_agreement_error(jf, tc, np.zeros_like(tc), theta)
            corrupt = (res_r > CORRUPT_ROT_DEG) | (res_t > CORRUPT_TRANS_MM)
            out[run] = dict(
                dir=d, ct=ct, sig=float(col['perturbation_sigma_t_mm']), seed=man['spec']['seed'],
                n=len(s), theta=theta, jf=jf, tc=tc, camR=camR, camt=camt, kR_true=kR, kt_true=kt,
                nominal=nominal['position_rms_mm'], nominal_rot=nominal['rotation_rms_deg'],
                est=self.value(run, 'wp4', REF + '|extrinsic=estimated', 'truth.fk_agreement.position_rms_mm'),
                tru=self.value(run, 'wp4', REF + '|extrinsic=truth', 'truth.fk_agreement.position_rms_mm'),
                est_rot=self.value(run, 'wp4', REF + '|extrinsic=estimated', 'truth.fk_agreement.rotation_rms_deg'),
                res_t=res_t, res_r=res_r, along=along,
                across=np.linalg.norm(err - along[:, None] * view, axis=1),
                dist=np.linalg.norm(true_cam, axis=1), corrupt=corrupt)
        self._kin = out
        return out

    def geometry(self):
        if getattr(self, '_geo', None) is not None:
            return self._geo
        path = os.path.join(self.out_dir, GEO_CACHE)
        cache = json.load(open(path)) if os.path.exists(path) else {}
        variants = [(f'method={m}|ridge_lambda={lam}|extrinsic=estimated', m, float(lam), 'estimated')
                    for m in METHODS_KIN for lam in LAMBDAS]
        variants.append((REF + '|extrinsic=truth', 'joint_trf', 1e-3, 'truth'))
        dirty = False
        for run, r in self.kinematic_runs().items():
            ct = r['ct']
            entry = cache.get(run, {})
            want = {v: self.value(run, 'wp4', v, 'truth.fk_agreement.position_rms_mm') for v, *_ in variants}
            if entry and all(v in entry.get('variants', {}) and abs(entry['variants'][v]['e_fk'] - want[v]) < 1e-6
                             for v in want):
                continue
            he = analyze.RunArtifacts(r['dir']).result('hand_eye_result.yaml', 'hand_eye_calibration')
            eR, et = metrics.rt_from_transform_dict(he['transform'])
            fix1 = ct == 'eye_in_hand'
            entry = {'nominal': metrics.fk_geometry_error(r['jf'], r['tc'], np.zeros_like(r['tc']), r['theta']),
                     'variants': {}}
            for v, method, lam, ext in variants:
                kR, kt = (eR, et) if ext == 'estimated' else (r['kR_true'], r['kt_true'])
                fit = analyze._wp4_solve(method, ct, r['theta'], kR, kt, r['camR'], r['camt'], r['jf'], fix1, lam)
                e_fk = metrics.fk_agreement_error(r['jf'], r['tc'], fit.corrections, r['theta'])['position_rms_mm']
                if abs(e_fk - want[v]) > 1e-6:
                    raise RuntimeError(f'{run} {v}: refit gives e_FK {e_fk:.6f} mm, results.csv {want[v]:.6f} mm')
                entry['variants'][v] = {'e_fk': e_fk, 'geo': metrics.fk_geometry_error(
                    r['jf'], r['tc'], fit.corrections, r['theta'])}
                if v == REF + '|extrinsic=estimated':
                    x = np.concatenate([fit.corrections[1 if fix1 else 0:].ravel(),
                                        geometry.rotation_matrix_to_rotvec(fit.mount_R), fit.mount_t])
                    J = kinematic_solver._numerical_jacobian(lambda y: kinematic_solver._residual_vector(
                        y, ct, r['theta'], eR, et, r['camR'], r['camt'], r['jf'], fix1, 0.0), x)
                    _, sv, Vt = np.linalg.svd(J, full_matrices=False)
                    entry['singular_values'] = sv.tolist()
                    entry['weakest_directions'] = Vt[-2:].tolist()
            cache[run] = entry
            dirty = True
        if dirty:
            with open(path, 'w') as f:
                json.dump(cache, f)
        self._geo = cache
        return cache


def detection_scale(kin, ct):
    rs = [r for r in kin.values() if r['ct'] == ct]
    al = np.concatenate([r['along'][~r['corrupt']] for r in rs])
    di = np.concatenate([r['dist'][~r['corrupt']] for r in rs])
    near = di < SCALE_FIT_MAX_DIST_M
    return float(np.sum(al[near] * di[near]) / np.sum(di[near] ** 2)) / 1000.0


def robot_level(runs, key_cal, key_nom='nominal'):
    """Average the paired difference over the runs of each simulated robot."""
    g = collections.defaultdict(list)
    for r in runs:
        g[(r['ct'], r['sig'], r['seed'])].append(r[key_nom] - r[key_cal])
    return np.array([np.mean(v) for v in g.values()])


# sections

def section_setup(b, out):
    s = out.setdefault('4.2 setup', {})
    for ct in MOUNTINGS:
        rp = [_num(r['value']) for r in b.select(work_package='wp4', calibration_type=ct, metric='detection.reprojection_rms_px.mean')]
        pts = [_num(r['value']) for r in b.select(work_package='wp4', calibration_type=ct, metric='detection.num_points_mean')]
        s[f'{ct}: reprojection RMS px, corners per detection'] = (round(_mean(rp), 3), round(_mean(pts), 1))
    s['runs per sweep and outcome'] = dict(collections.Counter(
        f"{m['spec'].get('sweep')}:{m.get('outcome')}" for _, m in b.runs.values()))
    kin = b.kinematic_runs()
    s['kinematic measurements in total'] = int(sum(r['n'] for r in kin.values()))
    s['kinematic measurement counts per requested level'] = dict(collections.Counter(
        (r['ct'], r['n']) for r in kin.values()))


def section_floor(b, out):
    s = out.setdefault('4.2 detection error', {})
    kin = b.kinematic_runs()
    bad = [(run, int(i), round(float(r['res_t'][i]), 1), round(float(r['res_r'][i]), 1))
           for run, r in kin.items() for i in np.where(r['corrupt'])[0]]
    s['corrupted detections (run, index, mm, deg)'] = bad
    s['corrupted detections: count, runs'] = (len(bad), len({x[0] for x in bad}))
    for ct in MOUNTINGS:
        rs = [r for r in kin.values() if r['ct'] == ct]
        ok = [~r['corrupt'] for r in rs]
        t = np.concatenate([r['res_t'][m] for r, m in zip(rs, ok)])
        ro = np.concatenate([r['res_r'][m] for r, m in zip(rs, ok)])
        al = np.concatenate([r['along'][m] for r, m in zip(rs, ok)])
        ac = np.concatenate([r['across'][m] for r, m in zip(rs, ok)])
        di = np.concatenate([r['dist'][m] for r, m in zip(rs, ok)])
        s[ct] = dict(n=int(len(t)), median_trans_mm=round(float(np.median(t)), 2),
                     rms_trans_mm=round(float(np.sqrt(np.mean(t ** 2))), 2),
                     median_rot_deg=round(float(np.median(ro)), 3),
                     rms_along_view_mm=round(float(np.sqrt(np.mean(al ** 2))), 2),
                     rms_across_view_mm=round(float(np.sqrt(np.mean(ac ** 2))), 2),
                     median_distance_m=round(float(np.median(di)), 2))
        # what is left once the systematic scale error is removed
        scale = detection_scale(kin, ct)
        al_r = al - scale * di * 1000.0
        by_dist = {}
        for lo, hi in ((0.0, 0.6), (0.6, 0.9), (0.9, 1.3)):
            m = (di >= lo) & (di < hi)
            by_dist[f'{lo}-{hi} m'] = (round(float(np.sqrt(np.mean(al_r[m] ** 2))), 2), int(m.sum()))
        s[ct].update(
            scale_pct=round(100 * scale, 3),
            seen_too_far=(int((al > 0).sum()), int(len(al)), round(float(np.mean(al > 0)), 3)),
            rms_along_view_scale_removed_mm=round(float(np.sqrt(np.mean(al_r ** 2))), 2),
            median_trans_scale_removed_mm=round(float(np.median(np.hypot(al_r, ac))), 2),
            rms_along_view_scale_removed_by_distance=by_dist)
    fx = (CAMERA_WIDTH / 2) / math.tan(CAMERA_HFOV_RAD / 2)
    dist = float(np.median(np.concatenate([r['dist'] for r in kin.values()])))
    s['px per 35 mm square at the median distance (1280 / 640)'] = (round(fx * 0.035 / dist), round(fx / 2 * 0.035 / dist))


def section_rq1(b, out):
    s = out.setdefault('RQ1 (tab:rq1, fig:rq1)', {})
    kin = list(b.kinematic_runs().values())
    rows = []
    for ct in MOUNTINGS:
        for sig in SIGMAS + (None,):
            rs = [r for r in kin if r['ct'] == ct and (sig is None or r['sig'] == sig)]
            d = robot_level(rs, 'est')
            row = dict(mounting=ct, sigma='all' if sig is None else sig,
                       nominal=round(_mean(r['nominal'] for r in rs), 2), calibrated=round(_mean(r['est'] for r in rs), 2),
                       robots_improved=f'{int((d > 0).sum())} / {len(d)}')
            row['ratio'] = round(row['nominal'] / row['calibrated'], 2)
            if sig is None:
                row['wilcoxon_p'] = float(f'{stats.wilcoxon(d).pvalue:.3g}')
            rows.append(row)
    s['table'] = rows
    for ct in MOUNTINGS:
        rs = [r for r in kin if r['ct'] == ct]
        s[f'{ct}: rotation nominal -> calibrated deg'] = (round(_mean(r['nominal_rot'] for r in rs), 3),
                                                          round(_mean(r['est_rot'] for r in rs), 3))
        ho_n = [b.value(run, 'wp4', REF + '|extrinsic=estimated', 'held_out.nominal_rms_mm.mean')
                for run, r in b.kinematic_runs().items() if r['ct'] == ct]
        ho_c = [b.value(run, 'wp4', REF + '|extrinsic=estimated', 'held_out.corrected_rms_mm.mean')
                for run, r in b.kinematic_runs().items() if r['ct'] == ct]
        s[f'{ct}: held-out nominal -> corrected mm'] = (round(_mean(ho_n), 2), round(_mean(ho_c), 2))
    for sig in SIGMAS:
        rs = [r for r in kin if r['ct'] == 'eye_to_hand' and r['sig'] == sig]
        clean = [r for r in rs if not r['corrupt'].any()]
        s[f'eye_to_hand true extrinsic, sigma {sig}: mean all / clean / runs with corrupt det.'] = (
            round(_mean(r['tru'] for r in rs), 2), round(_mean(r['tru'] for r in clean), 2), len(rs) - len(clean))


def section_rq2(b, out):
    s = out.setdefault('RQ2', {})
    kin = list(b.kinematic_runs().values())
    for ct in MOUNTINGS:
        tab = {}
        for sig in SIGMAS + (None,):
            rs = [r for r in kin if r['ct'] == ct and (sig is None or r['sig'] == sig)]
            tab['all' if sig is None else sig] = (round(_mean(r['nominal'] for r in rs), 2),
                                                  round(_mean(r['est'] for r in rs), 2),
                                                  round(_mean(r['tru'] for r in rs), 2))
        s[f'{ct} nominal / estimated / true extrinsic (tab:rq1)'] = tab
        cmp = {}
        for sig in SIGMAS:
            rs = [r for r in kin if r['ct'] == ct and r['sig'] == sig]
            d = np.array([r['tru'] - r['est'] for r in rs])
            rob = robot_level(rs, 'est', key_nom='tru')
            cmp[sig] = dict(estimated_ahead_runs=f'{int((d > 0).sum())}/{len(d)}',
                            estimated_ahead_robots=f'{int((rob > 0).sum())}/{len(rob)}',
                            mean_true_minus_estimated_mm=round(float(d.mean()), 3))
        s[f'{ct}: estimated vs true extrinsic per level'] = cmp
    eth = [r for r in kin if r['ct'] == 'eye_to_hand']
    clean = [r for r in eth if not r['corrupt'].any()]
    s['eye_to_hand true extrinsic: all runs / clean runs (n)'] = (round(_mean(r['tru'] for r in eth), 2),
                                                                 round(_mean(r['tru'] for r in clean), 2), len(clean))
    for ct in ('eye_to_hand', 'eye_in_hand'):
        pj = {}
        for j in range(1, 7):
            vals = []
            for ext in ('estimated', 'truth'):
                for unit in ('delta_t_perp_error_norm_mm', 'delta_r_perp_error_norm_mdeg'):
                    vals.append(round(_mean(_num(r['value']) for r in b.select(
                        work_package='wp4', calibration_type=ct, variant=f'{REF}|extrinsic={ext}',
                        metric=f'truth.per_joint.joint_{j}.{unit}')), 3))
            pj[f'joint_{j}'] = dict(est_mm=vals[0], est_mdeg=vals[1], true_mm=vals[2], true_mdeg=vals[3])
        s[f'{ct} per-joint parameter error (est vs true extrinsic)'] = pj
    cond = {}
    for ct in MOUNTINGS:
        for lam in LAMBDAS:
            v = [_num(r['value']) for r in b.rows if r['work_package'] == 'wp4' and r['calibration_type'] == ct
                 and r['metric'] == 'conditioning.condition_number' and f'ridge_lambda={lam}' in r['variant']]
            cond[f'{ct} lambda={lam}'] = float(f'{_mean(v):.4g}')
    s['condition number (tab:rq2-condition)'] = cond


def section_geometry(b, out):
    s = out.setdefault('RQ2 geometry (tab:rq2-geometry, fig:rq1)', {})
    kin = b.kinematic_runs()
    geo = b.geometry()
    ref_e, ref_t = REF + '|extrinsic=estimated', REF + '|extrinsic=truth'
    for ct in MOUNTINGS:
        tab = {}
        for sig in SIGMAS + (None,):
            rs = [run for run, r in kin.items() if r['ct'] == ct and (sig is None or r['sig'] == sig)]
            nom = np.array([geo[run]['nominal'] for run in rs])
            est = np.array([geo[run]['variants'][ref_e]['geo'] for run in rs])
            tru = np.array([geo[run]['variants'][ref_t]['geo'] for run in rs])
            g = collections.defaultdict(list)
            for run, d in zip(rs, nom - est):
                g[(kin[run]['sig'], kin[run]['seed'])].append(d)
            rob = np.array([np.mean(v) for v in g.values()])
            row = dict(nominal=round(float(nom.mean()), 2), estimated=round(float(est.mean()), 2),
                       true=round(float(tru.mean()), 2), robots_improved=f'{int((rob > 0).sum())} / {len(rob)}')
            if sig is None:
                row['wilcoxon_p'] = float(f'{stats.wilcoxon(rob).pvalue:.3g}')
            tab['all' if sig is None else sig] = row
        s[f'{ct}: geometry error nominal / estimated / true extrinsic'] = tab
    part = [metrics.fk_agreement_error(r['jf'], r['tc'], np.vstack([np.zeros((1, r['tc'].shape[1])), r['tc'][1:]]),
                                       r['theta'])['position_rms_mm'] for r in kin.values() if r['ct'] == 'eye_in_hand']
    s['eye_in_hand: e_FK caused by joint 1 alone (unobservable), mean'] = round(_mean(part), 2)
    opt = {}
    for m in METHODS_KIN:
        for lam in LAMBDAS:
            v = f'method={m}|ridge_lambda={lam}|extrinsic=estimated'
            opt[f'{m} lambda={lam}'] = {ct: dict(
                geo_mean=round(_mean(geo[run]['variants'][v]['geo'] for run, r in kin.items() if r['ct'] == ct), 2),
                geo_max=round(max(geo[run]['variants'][v]['geo'] for run, r in kin.items() if r['ct'] == ct), 2),
                e_fk_max=round(max(geo[run]['variants'][v]['e_fk'] for run, r in kin.items() if r['ct'] == ct), 1))
                for ct in MOUNTINGS}
    s['optimiser x ridge: geometry error mean / max, e_FK max (tab:rq3-optimiser)'] = opt
    byn = {}
    for ct in MOUNTINGS:
        for n in (40, 80, 150):
            rs = [run for run, r in kin.items() if r['ct'] == ct and r['n'] == n]
            cl = [run for run in rs if not kin[run]['corrupt'].any()]
            byn[f'{ct} {n}'] = dict(all=(round(_mean(geo[run]['variants'][ref_e]['geo'] for run in rs), 2), len(rs)),
                                    clean=(round(_mean(geo[run]['variants'][ref_e]['geo'] for run in cl), 2), len(cl)),
                                    true_extrinsic=round(_mean(geo[run]['variants'][ref_t]['geo'] for run in rs), 2))
    s['geometry error by measurement count, reference (tab:rq4-samples)'] = byn
    sv = {}
    for ct in MOUNTINGS:
        S = np.array([geo[run]['singular_values'] for run, r in kin.items() if r['ct'] == ct])
        sv[ct] = dict(largest=round(float(S[:, 0].mean()), 2),
                      three_smallest=[float(f'{x:.3g}') for x in S[:, -3:].mean(axis=0)],
                      max_of_smallest=float(f'{S[:, -1].max():.3g}'), max_of_second_smallest=float(f'{S[:, -2].max():.3g}'),
                      min_of_third_smallest=round(float(S[:, -3].min()), 2),
                      cond_without_two_weakest=round(float(np.mean(S[:, 0] / S[:, -3])), 1),
                      cond_all=float(f'{np.mean(S[:, 0] / np.maximum(S[:, -1], 1e-12)):.3g}'))
    s['singular values of the reference problem without ridge (mean over runs)'] = sv
    names = [f'joint_{j}.{p}' for j in range(2, 7) for p in ('t1', 't2', 'r1', 'r2')] + \
            ['board.r1', 'board.r2', 'board.r3', 'board.t1', 'board.t2', 'board.t3']
    loads = collections.defaultdict(lambda: np.zeros(len(names)))
    for run, r in kin.items():
        if r['ct'] == 'eye_in_hand':
            for k, vec in enumerate(geo[run]['weakest_directions'][::-1]):   # weakest first
                loads[k] += np.abs(np.array(vec)) ** 2
    s['eye_in_hand: weakest two directions, mean squared loading (top 4)'] = {
        f'direction {k + 1}': {names[i]: round(float(v[i] / v.sum()), 2) for i in np.argsort(-v)[:4]}
        for k, v in loads.items()}
    # what each weakest direction does at the flange: best rigid motion and remainder
    rig = collections.defaultdict(list)
    for run, r in kin.items():
        if r['ct'] != 'eye_in_hand':
            continue
        _, p0 = kinematic_model.forward_kinematics_batch(r['theta'], r['jf'], np.zeros_like(r['tc']))
        for k, vec in enumerate(geo[run]['weakest_directions'][::-1]):
            v = np.array(vec)[:20]
            _, p1 = kinematic_model.forward_kinematics_batch(
                r['theta'], r['jf'], kinematic_solver._corrections_from_free(1e-3 * v / np.abs(v).max(), True))
            a, c = p0 - p0.mean(0), p1 - p1.mean(0)
            U, _, Vt = np.linalg.svd(a.T @ c)
            R = (U @ np.diag([1.0, 1.0, np.sign(np.linalg.det(U @ Vt))]) @ Vt).T
            rv = geometry.rotation_matrix_to_rotvec(R)
            t = p1.mean(0) - R @ p0.mean(0)
            moved = np.sqrt(np.mean(np.sum((p1 - p0) ** 2, axis=1)))
            rest = np.sqrt(np.mean(np.sum((c - a @ R.T) ** 2, axis=1)))
            rig[k].append((abs(rv[2]) / max(np.linalg.norm(rv), 1e-15), abs(t[2]) / max(np.linalg.norm(t), 1e-15),
                           np.linalg.norm(rv) * 0.5 > np.linalg.norm(t), rest / moved))
    s['eye_in_hand: weakest directions as rigid motions of the arm'] = {
        f'direction {k + 1}': dict(rotation_share=f'{np.mean([x[2] for x in v]):.0%}',
                                   vertical_share_of_rotation_axis=round(float(np.mean([x[0] for x in v])), 3),
                                   vertical_share_of_translation=round(float(np.mean([x[1] for x in v])), 3),
                                   non_rigid_part_max=float(f'{max(x[3] for x in v):.2g}'))
        for k, v in rig.items()}


    def _T(R, t):
        M = np.eye(4); M[:3, :3] = R; M[:3, 3] = t
        return M
    E, D = [], []
    for run, r in kin.items():
        if r['ct'] != 'eye_to_hand':
            continue
        j = r['jf'][0]
        T0 = _T(kinematic_model._rpy_to_matrix(j.rpy0), j.xyz0)
        C = T0 @ _T(*kinematic_model.correction_transform(r['tc'][0, 0:2], r['tc'][0, 2:4],
                                                           kinematic_model.orthogonal_basis(j.axis))) @ np.linalg.inv(T0)
        he = analyze.RunArtifacts(r['dir']).result('hand_eye_result.yaml', 'hand_eye_calibration')
        Xe, Xt = _T(*metrics.rt_from_transform_dict(he['transform'])), _T(r['kR_true'], r['kt_true'])
        Xp = np.linalg.inv(C) @ Xt
        E.append(np.r_[(Xe[:3, 3] - Xt[:3, 3]) * 1e3, np.degrees(geometry.rotation_matrix_to_rotvec(Xt[:3, :3].T @ Xe[:3, :3]))])
        D.append(np.r_[(Xp[:3, 3] - Xt[:3, 3]) * 1e3, np.degrees(geometry.rotation_matrix_to_rotvec(Xt[:3, :3].T @ Xp[:3, :3]))])
    E, D = np.array(E), np.array(D)
    s['eye_to_hand: extrinsic error regressed on the absorbed placement (slope translation / rotation, n)'] = (
        round(float(np.sum(E[:, :3] * D[:, :3]) / np.sum(D[:, :3] ** 2)), 2),
        round(float(np.sum(E[:, 3:] * D[:, 3:]) / np.sum(D[:, 3:] ** 2)), 2), len(E))
    res = {}
    for ct in MOUNTINGS:
        rs = [run for run, r in kin.items() if r['ct'] == ct]
        res[ct] = tuple(round(_mean(b.value(run, 'wp4', v, 'in_sample.rms_after_mm') for run in rs), 3) for v in (ref_e, ref_t))
    s['in-sample residual mm, estimated / true extrinsic (reference)'] = res
    cond = {l: _mean(_num(r['value']) for r in b.rows if r['work_package'] == 'wp4' and r['calibration_type'] == 'eye_in_hand'
                     and r['metric'] == 'conditioning.condition_number' and f'ridge_lambda={l}' in r['variant']) for l in LAMBDAS}
    s['eye_in_hand: condition-number ratio between ridge weights (1/sqrt(lambda) predicts 31.6)'] = {
        '1e-9 / 1e-6': round(cond['1e-09'] / cond['1e-06'], 1), '1e-6 / 1e-3': round(cond['1e-06'] / cond['0.001'], 1)}
    corr = {}
    for ct in MOUNTINGS:
        T, G, H, B = [], [], [], []
        for run, r in kin.items():
            if r['ct'] != ct:
                continue
            for m in METHODS_KIN:
                for l in LAMBDAS:
                    v = f'method={m}|ridge_lambda={l}|extrinsic=estimated'
                    T.append(geo[run]['variants'][v]['e_fk']); G.append(geo[run]['variants'][v]['geo'])
                    H.append(b.value(run, 'wp4', v, 'held_out.corrected_rms_mm.mean'))
                    B.append(b.value(run, 'wp4', v, 'bootstrap.fk_spread_mm.mean'))
        T, G, H, B = map(np.array, (T, G, H, B))
        corr[ct] = dict(n=len(T), held_out_vs_geometry=(round(float(np.corrcoef(H, G)[0, 1]), 3), round(_spearman(H, G), 3)),
                        bootstrap_vs_geometry=(round(float(np.corrcoef(B, G)[0, 1]), 3), round(_spearman(B, G), 3)),
                        geometry_mean_max=(round(float(G.mean()), 2), round(float(G.max()), 2)))
    s['RQ5: correlation (pearson, spearman) of truth-free metrics with the geometry error'] = corr


def section_rq3(b, out):
    s = out.setdefault('RQ3', {})
    he = {}
    for ct in MOUNTINGS:
        for m in METHODS_HE:
            f = dict(work_package='wp3', calibration_type=ct, variant=f'method={m}')
            t = [_num(r['value']) for r in b.select(metric='truth.translation_error_mm', **f)]
            he[f'{ct} {m}'] = dict(true_mm=round(_mean(t), 2),
                                   true_deg=round(_mean(_num(r['value']) for r in b.select(metric='truth.rotation_error_deg', **f)), 3),
                                   held_out_mm=round(_mean(_num(r['value']) for r in b.select(metric='held_out.translation_mm.mean', **f)), 2),
                                   n=len(t))
    s['hand-eye formulations (tab:rq3-handeye)'] = he
    opt = {}
    for m in METHODS_KIN:
        for lam in LAMBDAS:
            v = f'method={m}|ridge_lambda={lam}|extrinsic=estimated'
            cell = {}
            for ct in MOUNTINGS:
                t = [_num(r['value']) for r in b.select(work_package='wp4', calibration_type=ct, variant=v,
                                                          metric='truth.fk_agreement.position_rms_mm')]
                cell[ct] = (round(_mean(t), 2), round(float(np.median(t)), 2), f'{100 * np.mean(np.array(t) > SEVERE_MM):.0f}%')
            opt[f'{m} lambda={lam}'] = cell
    s['optimiser x ridge (tab:rq3-optimiser): mean, median, % > 5 mm'] = opt


def section_rq4(b, out):
    s = out.setdefault('RQ4', {})
    he = collections.defaultdict(list)
    for r in b.select(work_package='wp3', variant='method=PARK', metric='truth.translation_error_mm'):
        if _num(r['image_noise_stddev']) == 0:
            he[(r['calibration_type'], int(r['num_samples']))].append(_num(r['value']))
    s['hand-eye Park, no image noise, by sample count (mean, n)'] = {
        f'{k[0]} {k[1]}': (round(_mean(v), 2), len(v)) for k, v in sorted(he.items())}
    kin = collections.defaultdict(list)
    for r in b.kinematic_runs().values():
        kin[(r['ct'], r['n'])].append(r['est'])
    s['kinematic reference, by sample count (mean, n)'] = {
        f'{k[0]} {k[1]}': (round(_mean(v), 2), len(v)) for k, v in sorted(kin.items())}
    noise = collections.defaultdict(list)
    for r in b.select(work_package='wp3', sweep='sim_wp3', variant='method=PARK', metric='truth.translation_error_mm', num_samples='40'):
        noise[(r['calibration_type'], _num(r['image_noise_stddev']))].append(_num(r['value']))
    s['image noise at 40 poses (mean, n)'] = {f'{k[0]} {k[1]:g}': (round(_mean(v), 2), len(v)) for k, v in sorted(noise.items())}
    v = {}
    for r in b.select(work_package='wp3', sweep='sim_wp3', variant='method=PARK', metric='truth.translation_error_mm'):
        v[(r['calibration_type'], r['num_samples'], r['image_noise_stddev'], r['seed'], r['camera_width'])] = _num(r['value'])
    res = {}
    for ct in MOUNTINGS:
        for ns in ('10', '40'):
            pairs = [(v[k], v[k[:4] + ('640',)]) for k in v
                     if k[0] == ct and k[1] == ns and k[4] == '1280' and k[:4] + ('640',) in v]
            a = [p[1] for p in pairs]
            bb = [p[0] for p in pairs]
            res[f'{ct} {ns} poses'] = dict(diff_mm=round(float(np.mean(np.array(bb) - np.array(a))), 2),
                                           seed_sd_mm=round(float(np.std(a + bb, ddof=1)), 2),
                                           paired_p=round(float(stats.wilcoxon(np.array(bb) - np.array(a)).pvalue), 2), n=len(pairs))
    s['resolution 1280 minus 640 (hand-eye sweep, paired by seed and noise)'] = res
    pooled = collections.defaultdict(list)
    within = collections.defaultdict(list)
    for r in b.select(work_package='wp3', variant='method=PARK', metric='truth.translation_error_mm'):
        pooled[r['camera_width']].append(_num(r['value']))
        if r['sweep'] == 'sim_wp3':
            within[r['camera_width']].append(_num(r['value']))
    s['resolution means: pooled vs within the hand-eye sweep'] = dict(
        pooled={w: round(_mean(x), 2) for w, x in pooled.items()}, within={w: round(_mean(x), 2) for w, x in within.items()})
    piv = {}
    for var in ('ransac=False', 'ransac=True'):
        rows = b.select(work_package='wp2', variant=var, metric='truth.translation_error_mm')
        piv[var] = dict(all=round(_mean(_num(r['value']) for r in rows), 2))
        for col in ('touch_noise_std_m', 'num_poses'):
            g = collections.defaultdict(list)
            for r in rows:
                g[_num(r[col])].append(_num(r['value']))
            piv[var][col] = {f'{k:g}': round(_mean(x), 2) for k, x in sorted(g.items())}
    s['pivot (tab:rq4-pivot)'] = piv


def section_rq5(b, out):
    s = out.setdefault('RQ5', {})
    kin = b.kinematic_runs()
    recs = collections.defaultdict(list)
    for r in b.rows:
        if r['work_package'] != 'wp4' or not r['variant'].endswith('extrinsic=estimated'):
            continue
        recs[(r['run_id'], r['variant'])].append(r)
    table = {}
    gates = {}
    lm = {}
    for ct in MOUNTINGS:
        T, H, I, B, W, G = [], [], [], [], [], []
        for (run, var), rr in recs.items():
            if kin[run]['ct'] != ct:
                continue
            m = {x['metric']: _num(x['value']) for x in rr}
            need = ('truth.fk_agreement.position_rms_mm', 'held_out.corrected_rms_mm.mean',
                    'in_sample.rms_after_mm', 'bootstrap.fk_spread_mm.mean', 'held_out.generalizes')
            if any(m.get(k) is None for k in need):
                continue
            T.append(m[need[0]]); H.append(m[need[1]]); I.append(m[need[2]]); B.append(m[need[3]]); G.append(m[need[4]])
            W.append(m[need[0]] > kin[run]['nominal'])
        T, H, I, B, W, G = map(np.array, (T, H, I, B, W, G))
        W = W.astype(bool)
        table[ct] = dict(n=len(T),
                         in_sample=(round(float(np.corrcoef(I, T)[0, 1]), 3), round(_spearman(I, T), 3)),
                         held_out=(round(float(np.corrcoef(H, T)[0, 1]), 3), round(_spearman(H, T), 3)),
                         bootstrap=(round(float(np.corrcoef(B, T)[0, 1]), 3), round(_spearman(B, T), 3)),
                         worse_than_nominal=f'{W.sum()} ({100 * W.mean():.0f}%)',
                         mean_spread_good_worse=(round(float(B[~W].mean()), 2), round(float(B[W].mean()), 2)))
        sev = T > SEVERE_MM
        gates[ct] = {'held-out: does not generalise': (f'{int(((G == 0) & sev).sum())}/{int(sev.sum())}',
                                                       f'{int(((G == 0) & W).sum())}/{int(W.sum())}',
                                                       f'{int(((G == 0) & ~W).sum())}/{int((~W).sum())}')}
        for th in (1.0, 2.0, 5.0):
            f = B > th
            gates[ct][f'spread > {th:g} mm'] = (f'{int((f & sev).sum())}/{int(sev.sum())}', f'{int((f & W).sum())}/{int(W.sum())}',
                                                 f'{int((f & ~W).sum())}/{int((~W).sum())}')
    for lam in LAMBDAS:
        v = f'method=joint_lm|ridge_lambda={lam}|extrinsic=estimated'
        rs = [run for run, r in kin.items() if r['ct'] == 'eye_in_hand']
        lm[lam] = (round(_mean(b.value(run, 'wp4', v, 'held_out.corrected_rms_mm.mean') for run in rs), 3),
                   round(_mean(b.value(run, 'wp4', v, 'truth.fk_agreement.position_rms_mm') for run in rs), 2))
    worse_truth = [b.value(run, 'wp4', f'{m}|extrinsic=truth', 'truth.fk_agreement.position_rms_mm') > kin[run]['nominal']
                   for run in kin if kin[run]['ct'] == 'eye_to_hand'
                   for m in (f'method={a}|ridge_lambda={l}' for a in METHODS_KIN for l in LAMBDAS)]
    s['correlations with true error (tab:rq5-correlation): (pearson, spearman)'] = table
    s['acceptance gates (tab:rq5-gate): severe / worse / good rejected'] = gates
    s['eye_in_hand joint_lm: held-out vs true, per lambda'] = lm
    s['eye_to_hand worse than nominal with TRUE extrinsic'] = f'{100 * np.mean(worse_truth):.0f}%'


def section_failures(b, out):
    s = out.setdefault('4.10 failure cases', {})
    kin = b.kinematic_runs()
    lm = [b.value(run, 'wp4', 'method=joint_lm|ridge_lambda=1e-09|extrinsic=estimated', 'truth.fk_agreement.position_rms_mm')
          for run, r in kin.items() if r['ct'] == 'eye_in_hand']
    s['eye_in_hand joint_lm 1e-9: n, min, max, all > 5 mm'] = (len(lm), round(min(lm), 2), round(max(lm), 2), all(x > SEVERE_MM for x in lm))
    z = [r for r in kin.values() if r['ct'] == 'eye_to_hand' and r['sig'] == 0.0]
